describe('Table Loading State', () => {
  beforeEach(() => {
    cy.visit('/table-data');
  });

  it('should display loading state while data is being fetched', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/table-data').as('fetchData');

    // Verify loading indicator is visible
    cy.get('[data-testid="table-loading-indicator"]').should('be.visible');
    cy.get('[data-testid="table-loading-indicator"]').should('contain', 'Loading...');

    // Verify table is empty
    cy.get('[data-testid="table-row"]').should('have.length', 0);

    // Verify table header is visible
    cy.get('[data-testid="table-header"]').should('be.visible');

    // Trigger the API call
    cy.wait('@fetchData');

    // Verify loading indicator disappears
    cy.get('[data-testid="table-loading-indicator"]').should('not.exist');

    // Verify table rows are populated
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify table data is displayed
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');
  });

  it('should handle error state when data fetch fails', () => {
    // Intercept the API call with error response
    cy.intercept('GET', '/api/table-data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('fetchDataError');

    // Verify loading indicator is visible
    cy.get('[data-testid="table-loading-indicator"]').should('be.visible');

    // Trigger the API call
    cy.wait('@fetchDataError');

    // Verify loading indicator disappears
    cy.get('[data-testid="table-loading-indicator"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="table-error-message"]').should('be.visible');
    cy.get('[data-testid="table-error-message"]').should('contain', 'Failed to load data');

    // Verify table rows are empty
    cy.get('[data-testid="table-row"]').should('have.length', 0);
  });
});
